export function evaluate({ inputs, time, seed, state }) {
  const g = inputs.gravity;
  const u = inputs.launchSpeed;
  const t = time; // seconds from launch
  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);
  const scale = 120; // px per metre
  const laneX = { toss: 150, drop: 450 };
  const baseY = 350; // ground line y coordinate
  // tossed ball
  const tossedVelocity = u - g * t;
  const tossedAcceleration = -g;
  const tossedHeight = u * t - 0.5 * g * t * t;
  const tossedY = baseY - tossedHeight * scale;
  // drop ball
  let dropVelocity, dropAcceleration, dropHeight, dropY, gateOpen;
  if (t < apexTime) {
    dropVelocity = 0;
    dropAcceleration = 0;
    dropHeight = apexHeight;
    gateOpen = false;
  } else {
    const dt = t - apexTime;
    dropVelocity = -g * dt;
    dropAcceleration = -g;
    dropHeight = apexHeight + dropVelocity * dt + 0.5 * (-g) * dt * dt;
    gateOpen = true;
  }
  const dropY = baseY - dropHeight * scale;
  // objects
  const objects = [];
  // lanes as panels
  objects.push(...sdk.panel({ x: 50, y: 50, w: 260, h: 340, title: "Toss", state: "", id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 350, y: 50, w: 260, h: 340, title: "Drop", state: "", id: "lane.drop" }));
  // balls
  objects.push(sdk.circle({ id: "ball.toss", x: laneX.toss, y: tossedY, diameter: 24 }));
  objects.push(sdk.circle({ id: "ball.drop", x: laneX.drop, y: dropY, diameter: 24 }));
  // velocity vectors
  const velScale = 20; // px per (m/s)
  const vDir = tossedVelocity >= 0 ? "up" : "down";
  objects.push(sdk.vector({ id: "vec.v.toss", origin: { x: laneX.toss, y: tossedY }, value: Math.abs(tossedVelocity) * velScale, direction: vDir, label: "v", scale: 1 }));
  const vDirDrop = dropVelocity >= 0 ? "up" : "down";
  objects.push(sdk.vector({ id: "vec.v.drop", origin: { x: laneX.drop, y: dropY }, value: Math.abs(dropVelocity) * velScale, direction: vDirDrop, label: "v", scale: 1 }));
  // acceleration vectors (dashed warm arrow)
  const aScale = 10;
  const aDir = tossedAcceleration >= 0 ? "up" : "down";
  objects.push(sdk.vector({ id: "vec.a.toss", origin: { x: laneX.toss, y: tossedY }, value: Math.abs(tossedAcceleration) * aScale, direction: aDir, label: "a", style: "dashed", scale: 1 }));
  const aDirDrop = dropAcceleration >= 0 ? "up" : "down";
  objects.push(sdk.vector({ id: "vec.a.drop", origin: { x: laneX.drop, y: dropY }, value: Math.abs(dropAcceleration) * aScale, direction: aDirDrop, label: "a", style: "dashed", scale: 1 }));
  // gate
  objects.push(sdk.gate({ id: "gate", x: laneX.drop, y: baseY - apexHeight * scale, open: gateOpen }));
  // callouts
  const calloutLinesToss = [];
  calloutLinesToss.push(`v: ${sdk.format(tossedVelocity, 2)} m/s`);
  calloutLinesToss.push(`a: ${sdk.format(tossedAcceleration, 2)} m/s²`);
  objects.push(...sdk.callout({ x: laneX.toss + 30, y: tossedY - 20, lines: calloutLinesToss, id: "callout.toss" }));
  const calloutLinesDrop = [];
  calloutLinesDrop.push(`v: ${sdk.format(dropVelocity, 2)} m/s`);
  calloutLinesDrop.push(`a: ${sdk.format(dropAcceleration, 2)} m/s²`);
  objects.push(...sdk.callout({ x: laneX.drop + 30, y: dropY - 20, lines: calloutLinesDrop, id: "callout.drop" }));
  // axes for each lane (optional, omitted to stay within object limit)
  const frame = sdk.frame(objects, { width: 640, height: 420 });
  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime: apexTime,
    apexHeight: apexHeight,
    tossedVelocity: tossedVelocity,
    tossedAcceleration: tossedAcceleration,
    tossedHeight: tossedHeight,
    dropVelocity: dropVelocity,
    dropAcceleration: dropAcceleration,
    dropHeight: dropHeight
  };
  const readouts = [
    { id: "tossedVelocity", value: tossedVelocity },
    { id: "tossedAcceleration", value: tossedAcceleration },
    { id: "dropVelocity", value: dropVelocity },
    { id: "dropAcceleration", value: dropAcceleration }
  ];
  return { frame, quantities, readouts };
}
